import fs from "node:fs";
import {
  createPublicClient,
  createWalletClient,
  custom,
  defineChain,
  type Abi,
  type Account,
  type Address,
  type Chain,
  type Hex,
  type PublicClient,
  type Transport,
  type WalletClient,
} from "viem";
import { privateKeyToAccount } from "viem/accounts";
import type { LocalChain } from "./local-chain.js";

/** Shape of contracts/artifacts/BindSettlement.json (generated by tools/compile-contract/generate.mjs). */
export interface BindSettlementArtifact {
  contractName: string;
  solcVersion: string;
  evmVersion: string;
  sourceSha256: string;
  abi: Abi;
  bytecode: Hex;
}

const ARTIFACT_URL = new URL("../../contracts/artifacts/BindSettlement.json", import.meta.url);

export function loadArtifact(): BindSettlementArtifact {
  return JSON.parse(fs.readFileSync(ARTIFACT_URL, "utf8")) as BindSettlementArtifact;
}

export interface ViemClients {
  publicClient: PublicClient<Transport, Chain>;
  walletClient: WalletClient<Transport, Chain, Account>;
  account: Account;
}

/**
 * Where a client talks to: a chain id and a viem transport. The in-process chain and a real node (Anvil over HTTP)
 * both fit this shape, so the same deployment code runs against either.
 */
export interface ChainTarget {
  chainId: number;
  transport: Transport;
  /** viem polling interval in milliseconds. Defaults to 5, the in-process value. */
  pollingInterval?: number;
}

/** viem public and wallet clients for any chain target. */
export function viemClientsOn(target: ChainTarget, privateKey: Hex): ViemClients {
  const chainDef = defineChain({
    id: target.chainId,
    name: "local",
    nativeCurrency: { name: "USDC", symbol: "USDC", decimals: 18 },
    rpcUrls: { default: { http: [] } },
  });
  const account = privateKeyToAccount(privateKey);
  const publicClient = createPublicClient({
    chain: chainDef,
    transport: target.transport,
    pollingInterval: target.pollingInterval ?? 5,
  });
  const walletClient = createWalletClient({ account, chain: chainDef, transport: target.transport });
  return { publicClient, walletClient, account };
}

/** viem public and wallet clients whose transport is the in-process chain. */
export function viemClients(chain: LocalChain, privateKey: Hex): ViemClients {
  return viemClientsOn({ chainId: chain.chainId, transport: custom({ request: chain.request as any }) }, privateKey);
}

/** Deploys the committed BindSettlement artifact to any chain target, signed by a funded key. */
export async function deployBindSettlementOn(
  target: ChainTarget,
  privateKey: Hex
): Promise<ViemClients & { address: Address; abi: Abi }> {
  const artifact = loadArtifact();
  const { publicClient, walletClient, account } = viemClientsOn(target, privateKey);
  const hash = await walletClient.deployContract({
    abi: artifact.abi,
    bytecode: artifact.bytecode,
    gas: 5_000_000n,
  });
  const receipt = await publicClient.waitForTransactionReceipt({ hash });
  if (receipt.status !== "success" || !receipt.contractAddress) {
    throw new Error(`BindSettlement deployment failed (status ${receipt.status})`);
  }
  return { address: receipt.contractAddress, abi: artifact.abi, publicClient, walletClient, account };
}

/** Shape of contracts/artifacts/helpers/<Name>.json (generated by tools/compile-contract/generate.mjs). */
export interface HelperArtifact {
  contractName: string;
  solcVersion: string;
  evmVersion: string;
  sourceSha256: string;
  abi: Abi;
  bytecode: Hex;
}

const HELPER_ARTIFACT_DIR = new URL("../../contracts/artifacts/helpers/", import.meta.url);

/** Loads a test helper artifact by contract name, for example `ReentrantSupplier`. */
export function loadHelperArtifact(name: string): HelperArtifact {
  return JSON.parse(fs.readFileSync(new URL(`${name}.json`, HELPER_ARTIFACT_DIR), "utf8")) as HelperArtifact;
}

/** Deploys a helper artifact with no constructor arguments to the in-process chain, signed by a funded key. */
export async function deployHelperArtifact(
  chain: LocalChain,
  privateKey: Hex,
  artifact: HelperArtifact
): Promise<ViemClients & { address: Address; abi: Abi }> {
  const { publicClient, walletClient, account } = viemClients(chain, privateKey);
  const hash = await walletClient.deployContract({ abi: artifact.abi, bytecode: artifact.bytecode, gas: 5_000_000n });
  const receipt = await publicClient.waitForTransactionReceipt({ hash });
  if (receipt.status !== "success" || !receipt.contractAddress) {
    throw new Error(`${artifact.contractName} deployment failed (status ${receipt.status})`);
  }
  return { address: receipt.contractAddress, abi: artifact.abi, publicClient, walletClient, account };
}

/** Deploys to the in-process chain. Behaviour is unchanged; the Anvil suite uses deployBindSettlementOn. */
export async function deployBindSettlement(
  chain: LocalChain,
  privateKey: Hex
): Promise<ViemClients & { address: Address; abi: Abi }> {
  return deployBindSettlementOn({ chainId: chain.chainId, transport: custom({ request: chain.request as any }) }, privateKey);
}
